/*
 * ADAM — القوانين والمقاسات الرسمية (الجزء ج): القوة، ألعاب القوى، الجمباز والاستعراض، الشتوية، ورياضات متنوعة
 * Official rules & dimensions, part C (kind: rules, prefix rl_).
 *
 * Values come from the governing-body rulebook named in `source`.
 * Where a value differs by level, age or sex, the value says so.
 * Validate with:  node tools/check-hub.js rules library/sport-rules-c.js
 */

/* item: label + value, each { ar, en } */
const i = (lAr, lEn, vAr, vEn) => ({ label: { ar: lAr, en: lEn }, value: { ar: vAr, en: vEn } });
/* section */
const s = (id, ...items) => ({ id, items });
/* rule entry */
const r = (sport, source, ...sections) => ({ id: 'rl_' + sport, sport, source, sections });

